parameters.text:
=Du bist Produktentwickler für digitale Etsy-Downloads im deutschsprachigen Markt.

BUCH-KONTEXT:
Titel: {{ $('Buch-Daten').first().json.titel }}
Untertitel: {{ $('Buch-Daten').first().json.untertitel }}
Nische: {{ $('Buch-Daten').first().json.nische }}
Beschreibung: {{ $('Buch-Daten').first().json.beschreibung }}
Kapitelstruktur (JSON): {{ $('Buch-Daten').first().json.planungsdaten }}

MANUSKRIPT (Auszug, ggf. gekürzt):
{{ String($json.text || '(Manuskript nicht verfügbar – arbeite dann allein mit dem Buch-Kontext oben)').slice(0, 60000) }}

AUFGABE:
Entwickle GENAU 5 eigenständige digitale Produkte (PDF-Downloads), die aus den Themen dieses Buches abgeleitet sind und sich auf Etsy verkaufen lassen. Erlaubte Typen: Checkliste, Planer, Tracker, Tagebuch/Journal, Workbook, Vorlagen-Set.

REGELN:
- Stütze dich auf die tatsächlichen Methoden, Begriffe, Modelle und Schritt-für-Schritt-Systeme aus dem Manuskript. Verwende dieselbe Terminologie wie das Buch.
- Jedes Produkt muss OHNE das Buch eigenständig funktionieren und echten Nutzen bieten
- Kein 1:1-Kopieren von Buchinhalten, sondern praktische Umsetzungs-Werkzeuge zu den Themen
- Titel auf Deutsch, konkret und suchtauglich (was würde jemand bei Etsy eingeben?)
- Preis zwischen 2.99 und 7.99 EUR, je nach Umfang
- inhalt_konzept: 3-5 Sätze, die exakt beschreiben, welche Seiten/Elemente das PDF enthält
- quellen_auszug: 150-300 Wörter aus dem Manuskript verdichtet – die konkreten Methoden, Begriffe, Schrittfolgen, Fragen und Beispiele, die für GENAU dieses Produkt gebraucht werden. Das ist die inhaltliche Arbeitsgrundlage für die spätere Erstellung, also konkret und nicht zusammenfassend-vage.

Antworte NUR mit validem JSON, exakt in diesem Format, ohne Markdown:
{"produkte":[{"nr":1,"typ":"Checkliste","titel":"...","beschreibung_kurz":"...","inhalt_konzept":"...","quellen_auszug":"...","preis_eur":4.99}]}

parameters.message:
=🛒 NEUE ETSY-PRODUKTE ZUR FREIGABE 🛒

BUCH: {{ $('Buch-Daten').first().json.titel }}
AUTOR: {{ $('Buch-Daten').first().json.autor }}

{{ $json.output.produkte.map(p => '━━━━━━━━━━━━━━━━━━━━\nPRODUKT ' + p.nr + ': ' + p.titel + '\nTyp: ' + p.typ + ' | Preis: ' + p.preis_eur + ' €\n' + p.beschreibung_kurz + '\n\nINHALT: ' + p.inhalt_konzept + '\n').join('\n') }}

Wähle unten aus, welche Produkte produziert werden sollen.

parameters.jsCode:
const produkte = $('Produkt-Strategie-Agent').first().json.output.produkte || [];
const buch = $('Buch-Daten').first().json;

// Etsy-Dateien landen im Unterordner "Etsy" des Buches (Spalte Etsy-Ordner-ID
// im Buch-Master). Fallback auf den Buch-Hauptordner, falls die Spalte leer ist.
const zeile = $('Buch laden').first().json || {};
const etsyOrdner = String(zeile['Etsy-Ordner-ID'] || '').trim() || buch.ordner_id;

const antwort = $json.data || $json;
// Seit 11.09.2026 ist die Freigabe-Mail deaktiviert (Entscheidung Betreiber): ohne Antwort werden alle
// Produkte produziert. Kontrolle vor dem Veroeffentlichen (Morgen-Mail, Spalte "Redaktionell geprueft am").
// Freigabe-Mail wieder aktivieren = Auswahl per Mail wie frueher.
const hatAuswahl = Object.keys(antwort || {}).some(k => /^produkt_\d+$/.test(k));
const ausgewaehlt = [];
produkte.forEach((p, i) => {
  const wahl = antwort['produkt_' + (i + 1)] || '';
  if (!hatAuswahl || wahl.indexOf('Produzieren') === 0) {
    ausgewaehlt.push({ json: Object.assign({}, p, {
      buch_id: buch.buch_id,
      buch_titel: buch.titel,
      autor: buch.autor,
      ordner_id: buch.ordner_id,
      etsy_ordner_id: etsyOrdner
    }) });
  }
});
if (ausgewaehlt.length === 0) {
  throw new Error('Keine Produkte ausgewählt – Workflow beendet.');
}
return ausgewaehlt;

// ===== PREIS ZENTRAL =====
// PREIS_PHASE umstellen, sobald die ersten Verkaeufe / Reviews da sind:
//   'start'     = Einstiegspreise (Shop ohne Verkaeufe und ohne Reviews)
//   'etabliert' = regulaere Preise
// Gilt fuer das Etsy-Listing UND fuer den Eintrag im Blatt "Etsy-Produkte".
// Format immer mit Punkt als Trenner.
const PREIS_PHASE = 'start';

const STAFFEL = {
  start:     { checkliste: '1.90', vorlage: '2.90', workbook: '4.90', bundle: '7.90',  fallback: '2.90' },
  etabliert: { checkliste: '2.90', vorlage: '4.90', workbook: '7.90', bundle: '12.90', fallback: '4.90' }
};

const z = $input.first().json;
const seo = $('SEO-Agent').first().json.output || {};
const p = $('Loop Produkte').first().json || {};
const pdf = $('PDF ablegen').first().json || {};

if (!z.shop_id) throw new Error('Keine shop_id vom Token-Workflow erhalten.');

const typ = String(p.typ || '').toLowerCase();
const hat = function () {
  const w = Array.prototype.slice.call(arguments);
  return w.some(function (x) { return typ.indexOf(x) !== -1; });
};

// --- Preis-Kategorie aus dem Produkttyp (Reihenfolge ist wichtig) ---
let kategorie = 'fallback';
if (hat('bundle', 'paket', 'komplett', 'sammlung')) kategorie = 'bundle';
else if (hat('workbook', 'arbeitsheft', 'arbeitsbuch', 'journal', 'tagebuch', 'kurs', 'leitfaden', 'guide', 'ratgeber')) kategorie = 'workbook';
else if (hat('vorlage', 'planer', 'kalender', 'tracker', 'template', 'arbeitsblatt', 'worksheet', 'protokoll', 'kartenset', 'set', 'system')) kategorie = 'vorlage';
else if (hat('checkliste', 'spickzettel', 'cheat', 'uebersicht', 'übersicht')) kategorie = 'checkliste';

const tabelle = STAFFEL[PREIS_PHASE] || STAFFEL.start;
const PREIS_EUR = tabelle[kategorie] || tabelle.fallback;

// --- Taxonomie (unveraendert) ---
let taxonomy = 1305;
if (typ.indexOf('planer') !== -1 || typ.indexOf('kalender') !== -1) taxonomy = 12476;
else if (typ.indexOf('journal') !== -1 || typ.indexOf('tagebuch') !== -1) taxonomy = 12475;
else if (typ.indexOf('checkliste') !== -1 || typ.indexOf('arbeitsblatt') !== -1 || typ.indexOf('worksheet') !== -1 || typ.indexOf('vorlage') !== -1) taxonomy = 12471;
else if (typ.indexOf('leitfaden') !== -1 || typ.indexOf('guide') !== -1 || typ.indexOf('lern') !== -1 || typ.indexOf('ratgeber') !== -1) taxonomy = 12474;

// Etsy erlaubt in Tags Buchstaben, Zahlen, Leerzeichen und Bindestriche
const tags = (seo.tags || [])
  .map(t => String(t).replace(/[^0-9a-zA-ZäöüÄÖÜß \-]/g, '').trim().slice(0, 20))
  .filter(t => t.length > 0)
  .slice(0, 13);

// Etsy erlaubt in Materials NUR Buchstaben, Zahlen und Leerzeichen
const standard = ['PDF Datei', 'Digitaler Download', 'Druckvorlage', 'DIN A4'];
const roh = (Array.isArray(seo.materials) && seo.materials.length) ? seo.materials : standard;
const materials = roh
  .map(m => String(m).replace(/[^0-9a-zA-ZäöüÄÖÜß ]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 45))
  .filter(m => m.length > 0)
  .slice(0, 13);

const titel = String(seo.etsy_titel || p.titel || 'Digitales Produkt').slice(0, 140);
const beschreibung = String(seo.beschreibung || '');
if (!beschreibung) throw new Error('SEO-Agent hat keine Beschreibung geliefert.');

const altText = String(seo.alt_text || (titel + ' - digitale PDF-Vorlage zum Ausdrucken')).slice(0, 250);
const basis = (String(p.titel || 'Produkt').replace(/[^0-9a-zA-Z]/g, '_').slice(0, 40) || 'Produkt');

return [{ json: {
  preis: PREIS_EUR,
  preis_kategorie: kategorie,
  preis_phase: PREIS_PHASE,
  api_key: z.api_key,
  access_token: z.access_token,
  shop_id: z.shop_id,
  taxonomy_id: taxonomy,
  titel: titel,
  beschreibung: beschreibung,
  tags: tags.join(','),
  materials: materials.join(','),
  alt_text: altText,
  bilddatei: basis + '_mockup.jpg',
  pdf_id: String(pdf.id || ''),
  dateiname: String(pdf.name || 'Produkt.pdf')
}}];

let h = String($json.output || '').trim();
h = h.replace(/^```(?:html)?\s*/i, '').replace(/```\s*$/, '').trim();
const i = h.toLowerCase().indexOf('<!doctype');
if (i > 0) { h = h.slice(i); }
if (!h) { throw new Error('Content-Agent hat kein HTML geliefert.'); }
return [{ json: { html: h } }];

// Bestimmt, fuer welches Buch Etsy-Produkte erzeugt werden.
// 1) Buch-ID vorgegeben (Formular, WF04 nach der Freigabe, Testlauf-Starter): genau dieses Buch.
// 2) Keine Buch-ID: automatisch das erste Buch im Buch-Master, das eine Buch-ID und einen
//    Buchordner hat, aber noch keine einzige Zeile im Blatt "Etsy-Produkte".
function startDaten() {
  try { return $('Etsy-Fabrik Start').first().json || {}; } catch (e) {}
  try { return $('Testlauf-Start').first().json || {}; } catch (e) {}
  return {};
}
const gewuenscht = String(startDaten().buch_id || '').trim();
const buecher = $('Auswahl: Buecher').all().map(i => i.json || {}).filter(b => String(b.Buchtitel || '').trim());
const id = b => String(b['Buch-ID'] == null ? '' : b['Buch-ID']).trim();

if (gewuenscht) {
  const b = buecher.find(x => id(x) === gewuenscht);
  if (!b) throw new Error('Buch-ID "' + gewuenscht + '" steht nicht im Buch-Master.');
  // Automatischer Start aus WF03 (auch bei einem WF03-Neulauf): hat das Buch schon Etsy-Produkte,
  // passiert nichts, damit keine doppelten Entwuerfe entstehen. Manuell (Formular/Starter) geht es trotzdem.
  const schonDa = $('Auswahl: Etsy-Bestand').all().some(i => id(i.json || {}) === gewuenscht);
  if (schonDa && String(startDaten().quelle || '').indexOf('WF03') === 0) {
    return [];
  }
  return [{ json: { buch_id: gewuenscht, auswahl: 'vorgegeben', titel: b.Buchtitel } }];
}

const mitEtsy = new Set($('Auswahl: Etsy-Bestand').all().map(i => id(i.json || {})).filter(Boolean));
const ohneId = buecher.filter(b => !id(b)).map(b => b.Buchtitel);
const offen = buecher.filter(b => id(b) && String(b['Ordner-ID'] || '').trim() && !mitEtsy.has(id(b)));

if (offen.length === 0) {
  if (ohneId.length) {
    throw new Error('Kein Buch automatisch waehlbar. Ohne Buch-ID im Buch-Master (Spalte K): ' + ohneId.join(', '));
  }
  return []; // alle Buecher haben schon Etsy-Produkte, nichts zu tun
}
const b = offen[0];
return [{ json: { buch_id: id(b), auswahl: 'automatisch', titel: b.Buchtitel, offen_gesamt: offen.length, ohne_buch_id: ohneId } }];

// Bricht sauber ab, wenn der Strategie-Agent keine Produktliste geliefert hat
// (z. B. abgeschnittene Antwort). Sonst ginge eine leere Freigabe-Mail raus.
const j = $input.first().json || {};
const produkte = (j.output && Array.isArray(j.output.produkte)) ? j.output.produkte : [];
if (produkte.length === 0) {
  throw new Error('Produkt-Strategie-Agent hat keine Produkte geliefert. Rohdaten: ' + JSON.stringify(j).slice(0, 500));
}
return $input.all();

// Bevorzugt das fertige Print-PDF (Bestandsbuecher). Neue Buecher aus WF02 haben nur
// die DOCX-Datei PRINT_TEXT_..., die wird danach per Gotenberg in ein PDF umgewandelt.
const files = $input.all().map(i => i.json || {}).filter(f => f.id);
const pdf = files.find(f => /\.pdf$/i.test(String(f.name || '')));
const docx = files.find(f => /\.docx$/i.test(String(f.name || '')));
const f = pdf || docx;
if (!f) {
  throw new Error('Kein Manuskript im Buchordner gefunden (erwartet Print_*.pdf oder PRINT_TEXT_*.docx aus WF02).');
}
return [{ json: { id: f.id, name: f.name, typ: pdf ? 'pdf' : 'docx' } }];
